#!/usr/bin/env python3
"""
NLM Python Utility Module

Utility functions and helper classes for working with the NLM (Neural Learning Machine)
Python bindings. This module provides common operations, utilities, and helper
functions to make working with NLM more convenient and Pythonic.
"""

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from typing import Dict, List, Optional, Any, Tuple, Callable
import json
import os
import time
from enum import Enum

# Import NLM bindings (these would be generated by pybind11)
import pynlm

class SimulationPhase(Enum):
    """Enumeration for simulation phases."""
    EXPLORATION = "exploration"
    EXPLOITATION = "exploitation"
    CONSOLIDATION = "consolidation"
    SLEEP = "sleep"

class BrainUtils:
    """Utility functions for working with NLM Brain objects."""
    
    @staticmethod
    def analyze_brain_state(brain: pynlm.Brain) -> Dict[str, Any]:
        """Analyze brain state and return key metrics."""
        stats = {
            'neuron_count': brain.getTotalNeuronCount(),
            'synapse_count': brain.getTotalSynapseCount(),
            'region_count': brain.getRegionCount(),
            'active_neurons': brain.getActiveNeuronCount(),
            'firing_neurons': brain.getFiringNeuronCount(),
            'total_spikes': brain.getTotalSpikeCount(),
            'average_firing_rate': brain.getAverageFiringRate(),
            'excitation_inhibition_ratio': brain.getExcitationInhibitionRatio(),
            'developmental_stage': str(brain.getDevelopmentalStage()),
            'config_summary': brain.getConfig().summary() if brain.getConfig() else "No config"
        }
        return stats
    
    @staticmethod
    def get_brain_health(brain: pynlm.Brain) -> float:
        """Calculate brain health score (0-1)."""
        stats = BrainUtils.analyze_brain_state(brain)
        
        # Calculate health based on various factors
        health_factors = []
        
        # Neuron activity (optimal around 10-30% firing)
        firing_rate = stats['average_firing_rate']
        firing_health = min(1.0, firing_rate / 0.03)  # Healthy up to 30 Hz
        health_factors.append(firing_health)
        
        # Network connectivity (should be balanced)
        e_ir = stats['excitation_inhibition_ratio']
        if e_ir > 0.1 and e_ir < 10.0:
            connectivity_health = 1.0
        elif e_ir > 0.01 and e_ir < 100.0:
            connectivity_health = 0.7
        else:
            connectivity_health = 0.3
        health_factors.append(connectivity_health)
        
        # Population size
        population_health = min(1.0, stats['neuron_count'] / 5000.0)
        health_factors.append(population_health)
        
        # Overall health
        return np.mean(health_factors) if health_factors else 0.0
    
    @staticmethod
    def export_brain_data(brain: pynlm.Brain, filepath: str, format: str = 'json') -> bool:
        """Export brain data to file."""
        try:
            data = {
                'brain_stats': BrainUtils.analyze_brain_state(brain),
                'timestamp': time.time(),
                'config': brain.getConfig().summary() if brain.getConfig() else None
            }
            
            if format.lower() == 'json':
                with open(filepath, 'w') as f:
                    json.dump(data, f, indent=2, default=str)
            elif format.lower() == 'csv':
                df = pd.DataFrame([data['brain_stats']])
                df.to_csv(filepath, index=False)
            else:
                raise ValueError(f"Unsupported format: {format}")
            
            print(f"Brain data exported to {filepath}")
            return True
            
        except Exception as e:
            print(f"Failed to export brain data: {e}")
            return False
    
    @staticmethod
    def import_brain_data(filepath: str) -> Optional[Dict[str, Any]]:
        """Import brain data from file."""
        try:
            if not os.path.exists(filepath):
                print(f"File not found: {filepath}")
                return None
            
            if filepath.endswith('.json'):
                with open(filepath, 'r') as f:
                    data = json.load(f)
            elif filepath.endswith('.csv'):
                df = pd.read_csv(filepath)
                data = {'brain_stats': df.to_dict('records')[0]}
            else:
                print(f"Unsupported file format: {filepath}")
                return None
            
            return data
            
        except Exception as e:
            print(f"Failed to import brain data: {e}")
            return None
    
    @staticmethod
    def create_brain_from_template(template_name: str) -> pynlm.Brain:
        """Create brain from predefined template."""
        templates = {
            'small': {
                'neuron_count': 100,
                'region_count': 1,
                'connection_probability': 0.1,
                'stdp_ltp_weight': 0.01
            },
            'medium': {
                'neuron_count': 1000,
                'region_count': 2,
                'connection_probability': 0.15,
                'stdp_ltp_weight': 0.02
            },
            'large': {
                'neuron_count': 5000,
                'region_count': 4,
                'connection_probability': 0.2,
                'stdp_ltp_weight': 0.025
            },
            'research': {
                'neuron_count': 10000,
                'region_count': 8,
                'connection_probability': 0.12,
                'stdp_ltp_weight': 0.03,
                'synaptogenesis_rate': 0.0005,
                'pruning_rate': 0.00005
            }
        }
        
        if template_name not in templates:
            raise ValueError(f"Unknown template: {template_name}")
        
        config = pynlm.createDefaultConfig()
        template = templates[template_name]
        
        for key, value in template.items():
            config.set(key, value)
        
        brain = pynlm.createBrain(config)
        brain.initialize()
        
        print(f"Created brain using template: {template_name}")
        print(f"Configuration: {template}")
        
        return brain
class AgentUtils:
    """Utility functions for working with NLM AgentBrain objects."""
    
    @staticmethod
    def analyze_agent_state(agent: pynlm.AgentBrain, world: pynlm.SimpleWorld) -> Dict[str, Any]:
        """Analyze agent state and behavior."""
        stats = {
            'neuromodulation_level': agent.getNeuromodulationLevel(),
            'curiosity_level': agent.getCuriosityLevel(),
            'novelty_level': agent.getNoveltyLevel(),
            'prediction_error': agent.getPredictionError(),
            'developmental_stage': str(agent.getDevelopmentalStage()),
            'simulation_time': world.getSimulationTime(),
            'world_size': (world.getWidth(), world.getHeight()),
            'brain_stats': BrainUtils.analyze_brain_state(agent.getBrain())
        }
        return stats
    
    @staticmethod
    def get_action_statistics(actions: List[pynlm.Action]) -> Dict[str, Any]:
        """Analyze statistics from a sequence of actions."""
        if not actions:
            return {'total_actions': 0}
        
        action_types = []
        action_counts = {}
        
        for action in actions:
            action_type = str(action.getType())
            action_types.append(action_type)
            action_counts[action_type] = action_counts.get(action_type, 0) + 1
        
        return {
            'total_actions': len(actions),
            'unique_actions': len(set(action_types)),
            'action_distribution': action_counts,
            'most_common_action': max(action_counts.items(), key=lambda x: x[1]) if action_counts else None
        }
    
    @staticmethod
    def calculate_efficiency(agent: pynlm.AgentBrain, world: pynlm.SimpleWorld, 
                           episode_length: int) -> float:
        """Calculate agent efficiency score."""
        # Get brain stats
        brain_stats = BrainUtils.analyze_brain_state(agent.getBrain())
        
        # Calculate efficiency based on various factors
        efficiency_factors = []
        
        # Firing efficiency (optimal activity)
        firing_rate = brain_stats['average_firing_rate']
        firing_efficiency = min(1.0, firing_rate / 0.03)
        efficiency_factors.append(firing_efficiency)
        
        # Neuromodulation balance
        neuromod = agent.getNeuromodulationLevel()
        neuromod_efficiency = 1.0 / (1.0 + abs(neuromod - 0.5))
        efficiency_factors.append(neuromod_efficiency)
        
        # Developmental progress
        dev_stage = agent.getDevelopmentalStage()
        dev_progress = {'Initial': 0.0, 'CriticalPeriod': 0.25, 'Maturation': 0.5, 
                       'Adult': 0.75, 'Aging': 1.0}
        developmental_efficiency = dev_progress.get(str(dev_stage), 0.5)
        efficiency_factors.append(developmental_efficiency)
        
        # Time efficiency
        time_efficiency = min(1.0, world.getSimulationTime() / episode_length)
        efficiency_factors.append(time_efficiency)
        
        return np.mean(efficiency_factors) if efficiency_factors else 0.0
class WorldUtils:
    """Utility functions for working with NLM SimpleWorld objects."""
    
    @staticmethod
    def analyze_world_state(world: pynlm.SimpleWorld) -> Dict[str, Any]:
        """Analyze world state and environment."""
        agent_body = world.getAgentBody()
        
        stats = {
            'world_size': {'width': world.getWidth(), 'height': world.getHeight()},
            'max_energy': world.getMaxEnergy(),
            'energy_decay_rate': world.getEnergyDecayRate(),
            'simulation_time': world.getSimulationTime(),
            'agent_position': {'x': agent_body.x, 'y': agent_body.y},
            'agent_orientation': agent_body.orientation,
            'agent_velocity': {'x': agent_body.velocityX, 'y': agent_body.velocityY},
            'agent_energy': agent_body.energy,
            'agent_health': agent_body.health,
            'agent_age': agent_body.age,
            'is_moving': agent_body.isMoving,
            'is_turning': agent_body.isTurning,
            'random_seed': world.getRandomSeed()
        }
        return stats
    
    @staticmethod
    def add_objects_randomly(world: pynlm.SimpleWorld, counts: Dict[str, int]) -> None:
        """Add objects randomly to world."""
        for obj_type, count in counts.items():
            for i in range(count):
                x = np.random.randint(1, world.getWidth() - 1)
                y = np.random.randint(1, world.getHeight() - 1)
                
                if obj_type == 'resource':
                    obj = pynlm.WorldObject(x, y, pynlm.WorldObjectType.Resource, 10.0)
                elif obj_type == 'hazard':
                    obj = pynlm.WorldObject(x, y, pynlm.WorldObjectType.Hazard, -5.0)
                elif obj_type == 'wall':
                    obj = pynlm.WorldObject(x, y, pynlm.WorldObjectType.Wall, 0.0, 0.5)
                elif obj_type == 'marker':
                    obj = pynlm.WorldObject(x, y, pynlm.WorldObjectType.Marker, 0.0, 0.3)
                else:
                    continue
                
                world.addObject(obj)
    
    @staticmethod
    def check_collision(world: pynlm.SimpleWorld, x: float, y: float) -> bool:
        """Check if position is valid (not colliding with walls/objects)."""
        return world.isValidPosition(x, y)
class SimulationUtils:
    """Utility functions for simulation management."""
    
    @staticmethod
    def run_simulation_episode(brain: pynlm.Brain, agent: pynlm.AgentBrain, 
                             world: pynlm.SimpleWorld, max_steps: int = 100) -> Dict[str, Any]:
        """Run a complete simulation episode."""
        episode_data = {
            'steps': [],
            'total_reward': 0.0,
            'final_state': None,
            'brain_stats_history': [],
            'action_history': [],
            'reward_history': []
        }
        
        for step in range(max_steps):
            # Update world
            world.update(0.1)
            
            # Get perception
            percept = world.getSensoryPercept()
            
            # Process sensory input
            agent.processSensoryInput(percept)
            
            # Brain processes
            brain.step(step)
            
            # Get action
            action = agent.decodeMotorCommand()
            episode_data['action_history'].append(action)
            
            # Apply action
            world.applyMotorCommand(action, world.getSimulationTime())
            
            # Calculate simple reward
            reward = SimulationUtils._calculate_simple_reward(world, agent)
            episode_data['reward_history'].append(reward)
            episode_data['total_reward'] += reward
            
            # Record state
            state = {
                'step': step,
                'world_time': world.getSimulationTime(),
                'brain_stats': BrainUtils.analyze_brain_state(brain),
                'agent_stats': AgentUtils.analyze_agent_state(agent, world),
                'world_stats': WorldUtils.analyze_world_state(world),
                'action': action,
                'reward': reward
            }
            episode_data['steps'].append(state)
            
            # Check if episode should end
            if SimulationUtils._check_episode_end(agent, world):
                break
        
        episode_data['final_state'] = {
            'world_time': world.getSimulationTime(),
            'total_reward': episode_data['total_reward'],
            'episode_length': len(episode_data['steps'])
        }
        
        return episode_data
    
    @staticmethod
    def _calculate_simple_reward(world: pynlm.SimpleWorld, agent: pynlm.AgentBrain) -> float:
        """Calculate simple reward based on state."""
        reward = 0.0
        
        # Reward for staying alive
        reward += agent.getBrain().getAgentBody().health * 0.01
        
        # Reward for exploration
        agent_body = agent.getBrain().getAgentBody()
        if agent_body.velocityX != 0 or agent_body.velocityY != 0:
            reward += 0.1
        
        # Small survival bonus
        reward += 0.001
        
        return reward
    
    @staticmethod
    def _check_episode_end(agent: pynlm.AgentBrain, world: pynlm.SimpleWorld) -> bool:
        """Check if episode should end."""
        agent_body = agent.getBrain().getAgentBody()
        
        # End if episode too long
        if world.getSimulationTime() > 10.0:
            return True
        
        # End if agent dies
        if agent_body.health <= 0.1:
            return True
        
        return False
    
    @staticmethod
    def batch_simulation(num_episodes: int, template_name: str = 'medium') -> List[Dict[str, Any]]:
        """Run multiple simulation episodes in batch."""
        print(f"Running batch simulation with {num_episodes} episodes using template: {template_name}")
        
        results = []
        
        for episode in range(num_episodes):
            print(f"Episode {episode + 1}/{num_episodes}")
            
            # Create brain for each episode
            brain = BrainUtils.create_brain_from_template(template_name)
            
            # Create world and agent
            world = pynlm.createSimpleWorld()
            world.configure(10, 10, 8, 8)
            world.reset()
            
            agent = pynlm.createAgentBrain(brain)
            agent.initialize(world)
            
            # Enable basic features
            agent.enableRewardModulation(True)
            agent.enableCuriosity(True)
            
            # Run episode
            episode_data = SimulationUtils.run_simulation_episode(brain, agent, world, max_steps=50)
            
            # Calculate episode statistics
            episode_stats = {
                'episode': episode + 1,
                'total_reward': episode_data['total_reward'],
                'episode_length': episode_data['final_state']['episode_length'],
                'average_firing_rate': np.mean([step['brain_stats']['average_firing_rate'] 
                                              for step in episode_data['steps']]),
                'final_brain_health': BrainUtils.get_brain_health(brain)
            }
            
            results.append(episode_stats)
            
            # Print episode summary
            print(f"  Reward: {episode_stats['total_reward']:.3f}")
            print(f"  Length: {episode_stats['episode_length']} steps")
            print(f"  Firing rate: {episode_stats['average_firing_rate']:.3f} Hz")
            print(f"  Brain health: {episode_stats['final_brain_health']:.3f}")
        
        return results
class DataAnalyzer:
    """Data analysis utilities for NLM simulation results."""
    
    @staticmethod
    def analyze_simulation_data(episode_data: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyze simulation episode data."""
        if not episode_data:
            return {}
        
        # Convert to DataFrame for analysis
        df = pd.DataFrame(episode_data)
        
        # Basic statistics
        analysis = {
            'episode_count': len(episode_data),
            'total_steps': sum(d['episode_length'] for d in episode_data),
            'total_reward': sum(d['total_reward'] for d in episode_data),
            'average_reward': np.mean([d['total_reward'] for d in episode_data]),
            'reward_std': np.std([d['total_reward'] for d in episode_data]),
            'reward_range': [min(d['total_reward'] for d in episode_data), 
                           max(d['total_reward'] for d in episode_data)],
            'average_episode_length': np.mean([d['episode_length'] for d in episode_data]),
            'firing_rate_stats': {
                'mean': np.mean([d['average_firing_rate'] for d in episode_data]),
                'std': np.std([d['average_firing_rate'] for d in episode_data]),
                'min': np.min([d['average_firing_rate'] for d in episode_data]),
                'max': np.max([d['average_firing_rate'] for d in episode_data])
            },
            'brain_health_stats': {
                'mean': np.mean([d['final_brain_health'] for d in episode_data]),
                'std': np.std([d['final_brain_health'] for d in episode_data]),
                'min': np.min([d['final_brain_health'] for d in episode_data]),
                'max': np.max([d['final_brain_health'] for d in episode_data])
            }
        }
        
        return analysis
    
    @staticmethod
    def plot_simulation_results(analysis: Dict[str, Any], save_path: Optional[str] = None) -> None:
        """Create plots from simulation analysis."""
        fig, axes = plt.subplots(2, 2, figsize=(12, 10))
        axes = axes.flatten()
        
        # Episode rewards histogram
        axes[0].hist(analysis.get('episode_rewards', []), bins=20, alpha=0.7, edgecolor='black')
        axes[0].set_title('Episode Rewards Distribution')
        axes[0].set_xlabel('Reward')
        axes[0].set_ylabel('Frequency')
        
        # Running average
        if 'running_average' in analysis:
            axes[1].plot(analysis['running_average'])
            axes[1].set_title('Running Average Reward')
            axes[1].set_xlabel('Episode')
            axes[1].set_ylabel('Average Reward')
        
        # Learning curve
        if 'learning_curve' in analysis:
            axes[2].plot(analysis['learning_curve'])
            axes[2].set_title('Learning Curve')
            axes[2].set_xlabel('Episode')
            axes[2].set_ylabel('Performance')
        
        # Brain health over time
        if 'brain_health_over_time' in analysis:
            axes[3].plot(analysis['brain_health_over_time'])
            axes[3].set_title('Brain Health Over Time')
            axes[3].set_xlabel('Episode')
            axes[3].set_ylabel('Health Score')
        
        plt.tight_layout()
        
        if save_path:
            plt.savefig(save_path, dpi=300, bbox_inches='tight')
            print(f"Plot saved to {save_path}")
        
        plt.show()
    
    @staticmethod
    def export_analysis_results(analysis: Dict[str, Any], filepath: str, 
                               format: str = 'json') -> bool:
        """Export analysis results to file."""
        try:
            if format.lower() == 'json':
                with open(filepath, 'w') as f:
                    json.dump(analysis, f, indent=2, default=str)
            elif format.lower() == 'csv':
                # Convert to CSV-friendly format
                csv_data = {}
                for key, value in analysis.items():
                    if isinstance(value, (list, dict)):
                        csv_data[key] = str(value)
                    else:
                        csv_data[key] = value
                
                df = pd.DataFrame([csv_data])
                df.to_csv(filepath, index=False)
            else:
                raise ValueError(f"Unsupported format: {format}")
            
            print(f"Analysis results exported to {filepath}")
            return True
            
        except Exception as e:
            print(f"Failed to export analysis results: {e}")
            return False
class MemoryManager:
    """Memory management utilities for NLM simulations."""
    
    @staticmethod
    def get_memory_usage() -> Dict[str, Any]:
        """Get current memory usage information."""
        import psutil
        import gc
        
        process = psutil.Process()
        memory_info = process.memory_info()
        
        return {
            'rss': memory_info.rss / (1024 * 1024),  # MB
            'vms': memory_info.vms / (1024 * 1024),  # MB
            'shared': memory_info.shared / (1024 * 1024),  # MB
            'text': memory_info.text / (1024 * 1024),  # MB
            'data': memory_info.data / (1024 * 1024),  # MB
            'dirty': memory_info.dirty / (1024 * 1024),  # MB
            'gc_objects': len(gc.get_objects()),
            'gc_threshold': gc.get_threshold()
        }
    
    @staticmethod
    def optimize_memory_for_simulation(target_memory_mb: float = 500) -> None:
        """Optimize memory usage for simulation."""
        import gc
        import psutil
        
        process = psutil.Process()
        
        while True:
            memory_mb = process.memory_info().rss / (1024 * 1024)
            
            if memory_mb <= target_memory_mb:
                break
            
            # Force garbage collection
            gc.collect()
            
            # Check memory again
            memory_mb = process.memory_info().rss / (1024 * 1024)
            
            if memory_mb <= target_memory_mb:
                break
            
            # Wait a bit
            time.sleep(0.1)
    
    @staticmethod
    def save_checkpoint_safely(brain: pynlm.Brain, filepath: str, 
                              max_retries: int = 3) -> bool:
        """Save checkpoint with retry logic."""
        for attempt in range(max_retries):
            try:
                success = brain.save(filepath)
                if success:
                    print(f"Checkpoint saved successfully: {filepath}")
                    return True
                else:
                    print(f"Checkpoint save failed (attempt {attempt + 1}/{max_retries})")
            except Exception as e:
                print(f"Checkpoint save error (attempt {attempt + 1}/{max_retries}): {e}")
            
            if attempt < max_retries - 1:
                time.sleep(1.0 * (attempt + 1))  # Exponential backoff
        
        print(f"Checkpoint save failed after {max_retries} attempts")
        return False
class PerformanceProfiler:
    """Performance profiling utilities for NLM simulations."""
    
    def __init__(self):
        self.timings = {}
        self.memory_samples = []
    
    def start_profiling(self, name: str):
        """Start profiling a specific operation."""
        self.timings[name] = {
            'start_time': time.time(),
            'samples': []
        }
    
    def stop_profiling(self, name: str) -> Dict[str, Any]:
        """Stop profiling and return timing information."""
        if name not in self.timings:
            raise ValueError(f"No profiling data for {name}")
        
        end_time = time.time()
        duration = end_time - self.timings[name]['start_time']
        
        result = {
            'duration': duration,
            'timestamp': end_time
        }
        
        self.timings[name].update(result)
        return result
    
    def sample_memory(self, name: str):
        """Sample memory usage for profiling."""
        if name not in self.timings:
            self.timings[name] = {
                'start_time': time.time(),
                'samples': []
            }
        
        from MemoryManager import MemoryManager
        memory_info = MemoryManager.get_memory_usage()
        self.timings[name]['samples'].append({
            'time': time.time(),
            'memory_mb': memory_info['rss']
        })
        
        self.memory_samples.append(memory_info)
    
    def get_profiling_summary(self) -> Dict[str, Any]:
        """Get profiling summary."""
        summary = {
            'total_operations': len(self.timings),
            'total_memory_samples': len(self.memory_samples),
            'operations': {}
        }
        
        for name, data in self.timings.items():
            summary['operations'][name] = {
                'duration': data.get('duration', 0),
                'sample_count': len(data.get('samples', [])),
                'avg_memory': np.mean([s['memory_mb'] for s in data.get('samples', [])]) if data.get('samples') else 0
            }
        
        if self.memory_samples:
            summary['memory_stats'] = {
                'max_rss_mb': max(s['rss'] for s in self.memory_samples),
                'avg_rss_mb': np.mean(s['rss'] for s in self.memory_samples),
                'min_rss_mb': min(s['rss'] for s in self.memory_samples)
            }
        
        return summary
    
    def save_profiling_data(self, filepath: str):
        """Save profiling data to file."""
        data = {
            'timings': self.timings,
            'memory_samples': self.memory_samples,
            'timestamp': time.time()
        }
        
        with open(filepath, 'w') as f:
            json.dump(data, f, indent=2, default=str)
        
        print(f"Profiling data saved to {filepath}")
    
    def load_profiling_data(self, filepath: str) -> bool:
        """Load profiling data from file."""
        try:
            with open(filepath, 'r') as f:
                data = json.load(f)
            
            self.timings = data['timings']
            self.memory_samples = data['memory_samples']
            
            print(f"Profiling data loaded from {filepath}")
            return True
            
        except Exception as e:
            print(f"Failed to load profiling data: {e}")
            return False
class NLMToolkit:
    """Main toolkit class providing access to all NLM utility functions."""
    
    def __init__(self):
        self.brain_utils = BrainUtils()
        self.agent_utils = AgentUtils()
        self.world_utils = WorldUtils()
        self.simulation_utils = SimulationUtils()
        self.data_analyzer = DataAnalyzer()
        self.memory_manager = MemoryManager()
        self.performance_profiler = PerformanceProfiler()
    
    def run_complete_experiment(self, experiment_config: Dict[str, Any]) -> Dict[str, Any]:
        """Run a complete experiment with the given configuration."""
        print(f"Running complete experiment: {experiment_config.get('name', 'Unnamed')}")
        
        # Create brain
        brain = self.brain_utils.create_brain_from_template(
            experiment_config.get('template', 'medium')
        )
        
        # Create world and agent
        world = pynlm.createSimpleWorld()
        world.configure(
            experiment_config.get('width', 10),
            experiment_config.get('height', 10),
            experiment_config.get('vision_width', 8),
            experiment_config.get('vision_height', 8)
        )
        world.reset()
        
        agent = pynlm.createAgentBrain(brain)
        agent.initialize(world)
        
        # Enable features
        if experiment_config.get('enable_reward_modulation', True):
            agent.enableRewardModulation(True)
        
        if experiment_config.get('enable_curiosity', True):
            agent.enableCuriosity(True)
        
        if experiment_config.get('enable_development', True):
            agent.enableDevelopment(True)
        
        # Run simulation
        episode_data = self.simulation_utils.run_simulation_episode(
            brain, agent, world, 
            max_steps=experiment_config.get('max_steps', 100)
        )
        
        # Analyze results
        analysis = self.data_analyzer.analyze_simulation_data([{
            'total_reward': episode_data['total_reward'],
            'episode_length': episode_data['final_state']['episode_length'],
            'average_firing_rate': np.mean([step['brain_stats']['average_firing_rate'] 
                                          for step in episode_data['steps']]),
            'final_brain_health': self.brain_utils.get_brain_health(brain)
        }])
        
        # Save data if requested
        if experiment_config.get('save_data'):
            data_file = f"{experiment_config.get('name', 'experiment')}_data.json"
            self.data_analyzer.export_analysis_results(
                analysis, data_file, experiment_config.get('data_format', 'json')
            )
        
        # Create visualization if requested
        if experiment_config.get('create_plots'):
            plot_file = f"{experiment_config.get('name', 'experiment')}_plots.png"
            self.data_analyzer.plot_simulation_results(analysis, plot_file)
        
        print(f"Experiment completed with reward: {analysis.get('total_reward', 0):.3f}")
        print(f"Brain health: {analysis.get('brain_health_stats', {}).get('mean', 0):.3f}")
        
        return {
            'brain': brain,
            'agent': agent,
            'world': world,
            'episode_data': episode_data,
            'analysis': analysis,
            'experiment_config': experiment_config
        }
    
    def run_batch_experiments(self, experiment_configs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Run multiple experiments in batch."""
        print(f"Running batch experiments with {len(experiment_configs)} configurations")
        
        results = []
        
        for i, config in enumerate(experiment_configs):
            print(f"\nExperiment {i + 1}/{len(experiment_configs)}: {config.get('name', 'Unnamed')}")
            
            try:
                result = self.run_complete_experiment(config)
                result['config_index'] = i
                results.append(result)
                
            except Exception as e:
                print(f"Experiment {i + 1} failed: {e}")
                results.append({
                    'config_index': i,
                    'error': str(e),
                    'success': False
                })
        
        # Analyze batch results
        successful_results = [r for r in results if r.get('success', True)]
        
        if successful_results:
            batch_analysis = self.data_analyzer.analyze_simulation_data([
                {
                    'total_reward': r['analysis']['total_reward'],
                    'episode_length': r['analysis']['episode_length'],
                    'average_firing_rate': r['analysis']['firing_rate_stats']['mean'],
                    'final_brain_health': r['analysis']['brain_health_stats']['mean']
                }
                for r in successful_results
            ])
        
        return results
# Global toolkit instance
_toolkit = NLMToolkit()

# Convenience functions
def create_brain(template: str = 'medium') -> pynlm.Brain:
    """Create a brain using the specified template."""
    return _toolkit.brain_utils.create_brain_from_template(template)

def run_experiment(config: Dict[str, Any]) -> Dict[str, Any]:
    """Run a complete experiment."""
    return _toolkit.run_complete_experiment(config)

def run_batch_experiments(configs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Run multiple experiments in batch."""
    return _toolkit.run_batch_experiments(configs)

def save_brain_data(brain: pynlm.Brain, filepath: str, format: str = 'json') -> bool:
    """Save brain data to file."""
    return BrainUtils.export_brain_data(brain, filepath, format)

def load_brain_data(filepath: str) -> Optional[Dict[str, Any]]:
    """Load brain data from file."""
    return BrainUtils.import_brain_data(filepath)

